import math

def calculate_R(N):
    R_N = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Calculate the fractional part {ab / (N+1)}
            fractional_part = (a * b) / N_plus_1 - math.floor((a * b) / N_plus_1)
            R_N += fractional_part
    return R_N

def calculate_TR(N):
    return (N**2 - 1) / 2

N_values = [8, 9, 10]
results = {}

print("--- R(N) Calculations ---")
for N in N_values:
    R_N = calculate_R(N)
    T_R_N = calculate_TR(N)
    results[N] = {'R(N)': R_N, 'T_R(N)': T_R_N}
    print(f"N={N}: R(N) = {R_N}, T_R(N) = {T_R_N}")

print("\n--- Results Dictionary ---")
print(results)
